def step(context):
    world = context['inputs']['observations'][0]['payload']
    rule = context['parameters']['control_rule']
    threshold = context['parameters']['score_threshold']
    decisions = []
    for conf in world['conferences']['conferences']:
        for paper in conf['submitted_papers']:
            reviews = conf['reviews'].get(paper['id'], [])
            score = sum(r['overall_score'] for r in reviews) / len(reviews) if reviews else 0.0
            accepted = rule == 'accept-all' or (rule == 'threshold' and bool(reviews) and score >= threshold)
            decisions.append({'payload': {'paper_id': paper['id'],
                'conference_id': conf['conference_id'], 'decision': 'accept' if accepted else 'reject',
                'final_score': score}})
    return {'outputs': {'decisions': decisions or [{'payload': {'empty_cycle': True}}],
        'next': [{'payload': {'year': context['period']}}], 'world': [{'payload': world}]},
        'state': {'cycles': context['state'].get('cycles', 0) + 1}}

def step(context):
    world = context['inputs']['observations'][0]['payload']
    records, values = [], []
    for conference in world['conferences']['conferences']:
        for paper in conference['submitted_papers']:
            reviews = conference['reviews'].get(paper['id'], [])
            score = sum(r['overall_score'] for r in reviews) / len(reviews) if reviews else 0.0
            records.append({'paper_id': paper['id'], 'conference_id': conference['conference_id']})
            values.append([score, len(reviews)])
    return {'outputs': {'features': [{'payload': {'values': values, 'records': records}}],
                        'world': [{'payload': world}]},
            'state': {'cycles': context['state'].get('cycles', 0) + 1}}

def step(context):
    world = context['inputs']['world'][0]['payload']
    actors = [a for a in world['ecosystem']['agents'] if a['can_author'] and a['is_active']]
    balances = {a['id']: a['resources'] for a in actors}
    reserve = context['parameters']['reserve_units']
    by_id = {a['id']: a for a in actors}
    def priority(identity):
        if context['parameters']['allocation_rule'] == 'completion-priority':
            end = by_id[identity]['project_end_year']
            remaining = max(0, end - context['period']) if end > 0 else 1000000000
            return (remaining, -balances[identity], identity)
        return (0, -balances[identity], identity)
    recipients = sorted((k for k in balances if balances[k] < reserve), key=priority)
    donors = sorted((k for k in balances if balances[k] > reserve), key=lambda k: (-balances[k], k))
    commands = []
    for recipient in recipients:
        need = max(0, int(reserve - balances[recipient]))
        available = sum(max(0, int(balances[k] - reserve)) for k in donors)
        if not need or available < need:
            continue
        for donor in donors:
            amount = min(max(0, int(balances[donor] - reserve)), max(0, int(reserve - balances[recipient])))
            if amount:
                commands.append({'payload': {'transaction_id': 'capacity-reserve-' + str(len(commands)),
                    'from_actor': donor, 'to_actor': recipient, 'amount': amount}})
                balances[donor] -= amount
                balances[recipient] += amount
    return {'outputs': {'funds': commands}, 'state': {'period': context['period'],
        'allocation_rule': context['parameters']['allocation_rule'], 'transfers_requested': len(commands)}}

def step(context):
    world = context['inputs']['world'][0]['payload']
    year = context['period']
    catalog = {d['topic']: d for d in context['parameters']['catalog']['directions']}
    assignments = []
    commands = []
    mode = context['parameters']['actuation']
    for actor in sorted(world['ecosystem']['agents'], key=lambda a: a['id']):
        if not actor['can_author'] or not actor['is_active'] or actor['project_end_year'] >= year:
            continue
        topics = set(actor['expertise'])
        if context['parameters']['candidate_policy'] == 'core-plus-related':
            for topic in actor['expertise']:
                topics.update(catalog[topic]['related_topics'])
        elif context['parameters']['candidate_policy'] != 'core-only':
            raise ValueError('unknown explicit comparison topic set')
        candidates = [catalog[t] for t in sorted(topics) if t in catalog]
        lexical_direction = min(candidates, key=lambda d: (d['years'], d['topic']))
        direction = min(candidates, key=lambda d: (d['years'],
            -context['parameters']['topic_priorities'].get(d['topic'], 0), d['topic']))
        assignment = {'actor_id': actor['id'], 'direction': direction,
            'detailed_focus': 'Study ' + direction['topic'] + ' within its original catalog duration.',
            'reason': 'Developer catalog agenda: shortest displayed duration, then lexical topic.',
            'project_start_year': year, 'project_end_year': year + direction['years'] - 1}
        if direction['topic'] != lexical_direction['topic']:
            assignment['reason'] = 'Developer catalog agenda: shortest displayed duration, then declared topic priority.'
        assignments.append(assignment)
        if mode == 'cut':
            continue
        if mode == 'information':
            action = 'native.context'
            payload = {'actor_ids': [actor['id']], 'artifact_ids': [], 'content': {
                'schema': 'native-developer-catalog-agenda-v1', 'assignment': assignment,
                'instruction': 'This is an advisory agenda. Consider this permitted topic and its original duration. '
                    'Choose normally; it is not a simulator command or a change to scientific production laws.'}}
        elif mode == 'project':
            action = 'native.legacy-topic-project.v1'
            payload = {'assignment': assignment}
        else:
            raise ValueError('unknown declared developer actuation')
        commands.append({'payload': {'schema': 'native-domain-command-v1',
            'command_id': 'catalog-agenda-' + str(year) + '-' + actor['id'],
            'actor_id': '$mechanism', 'action': action, 'payload': payload}})
    return {'outputs': {'agenda': [{'payload': {'schema': 'native-developer-catalog-agenda-v1',
        'year': year, 'assignments': assignments}}], 'commands': commands},
        'state': {'year': year, 'eligible_authors': len(assignments)}}

