    actors = [a for a in world['ecosystem']['agents'] if a.get('can_author') and a.get('is_active', True)]

    # Filter out authors whose projects extend into or beyond the current year
    eligible_actors = []
    for actor in actors:
        end_year = actor.get('project_end_year', -1)
        if end_year < year:  # Project already finished or never started
            eligible_actors.append(actor)

    for actor in sorted(eligible_actors, key=lambda a: a['id']):
        topics = set(actor.get('expertise', []))
        if context['parameters']['candidate_policy'] == 'core-plus-related':
            for topic in list(topics):
                if topic in catalog:
                    topics.update(catalog[topic].get('related_topics', []))
        elif context['parameters']['candidate_policy'] != 'core-only':
            raise ValueError('unknown explicit comparison topic set')

        candidates = [catalog[t] for t in sorted(topics) if t in catalog]
        if not candidates:
            continue

        # Select shortest duration, then lexical topic
        direction = min(candidates, key=lambda d: (d['years'], d['topic']))

        assignment = {
            'actor_id': actor['id'], 
            'direction': direction,
            'detailed_focus': 'Study ' + direction['topic'] + ' within its original catalog duration.',
            'reason': 'Developer catalog agenda: shortest displayed duration, then lexical topic.',
            'project_start_year': year, 
            'project_end_year': year + direction['years'] - 1
        }
        assignments.append(assignment)

        if mode == 'cut':
            continue
        elif mode == 'information':
            action = 'native.context'
            payload = {'actor_ids': [actor['id']], 'artifact_ids': [], 'content': {
                 'schema': 'native-developer-catalog-agenda-v1', 'assignment': assignment,
                 'instruction': 'This is an advisory agenda. Consider this permitted topic and its original duration. '
                     'Choose normally; it is not a simulator command or a change to scientific production laws.'}}
        elif mode == 'project':
            action = 'native.legacy-topic-project.v1'
            payload = {'assignment': assignment}
        else:
            raise ValueError('unknown declared developer actuation')

        commands.append({'payload': {'schema': 'native-domain-command-v1',
             'command_id': 'catalog-agenda-' + str(year) + '-' + actor['id'],
             'actor_id': '$mechanism', 'action': action, 'payload': payload}})

    return {'outputs': {'agenda': [{'payload': {'schema': 'native-developer-catalog-agenda-v1',
         'year': year, 'assignments': assignments}}], 'commands': commands},
         'state': {'year': year, 'eligible_authors': len(assignments)}}

